import {
  CreateCertificateCommand,
  DeleteCertificateCommand,
  GetCertificatesCommand,
  type LightsailClient,
} from "@aws-sdk/client-lightsail";
import { TAG_KEYS } from "@tc/core";
import { AwsError } from "../errors";

// The Lightsail certificate of a custom domain for a container service or a distribution (WPU-G8).
// The certificate name is generated by the caller (`tc-cert-...`, R11) and the domain is a checked
// value; nothing else of the customer's reaches AWS. One certificate per resource, so a retry finds it
// by its name and does not create a second one (R7).

const STATUSES = [
  "PENDING_VALIDATION",
  "ISSUED",
  "INACTIVE",
  "EXPIRED",
  "VALIDATION_TIMED_OUT",
  "REVOKED",
  "FAILED",
] as const;

const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;

/** The tags of a certificate: platform ids only (R11). An action has no order, so `tc:order` is left out. */
export function certificateTags(input: {
  env: string;
  customerId: string;
  resourceId: string;
}): { key: string; value: string }[] {
  if (!UUID.test(input.customerId) || !UUID.test(input.resourceId)) {
    throw new AwsError({ code: "internal", retryable: false });
  }
  return [
    { key: TAG_KEYS.env, value: input.env },
    { key: TAG_KEYS.customer, value: input.customerId },
    { key: TAG_KEYS.resource, value: input.resourceId },
  ];
}

export interface CertificateRecord {
  readonly name: string;
  readonly type: string;
  readonly value: string;
}

export interface CertificateFacts {
  readonly domain: string;
  readonly status: string;
  readonly records: readonly CertificateRecord[];
}

async function orNull<T>(call: () => Promise<T>): Promise<T | null> {
  try {
    return await call();
  } catch (error) {
    if (error instanceof AwsError && error.code === "not_found") return null;
    throw error;
  }
}

/** The certificate with this name, or null. Status words outside the known list read as UNKNOWN. */
export async function readCertificate(
  lightsail: LightsailClient,
  name: string,
): Promise<CertificateFacts | null> {
  const got = await orNull(() =>
    lightsail.send(
      new GetCertificatesCommand({ certificateName: name, includeCertificateDetails: true }),
    ),
  );
  const found = (got?.certificates ?? []).find(
    (c) => c.certificateName === name || c.certificateDetail?.name === name,
  );
  if (found === undefined) return null;
  const detail = found.certificateDetail;
  const status = detail?.status ?? "";
  return {
    domain: detail?.domainName ?? found.domainName ?? "",
    status: (STATUSES as readonly string[]).includes(status) ? status : "UNKNOWN",
    records: (detail?.domainValidationRecords ?? []).slice(0, 8).map((r) => ({
      name: r.resourceRecord?.name ?? "",
      type: r.resourceRecord?.type ?? "",
      value: r.resourceRecord?.value ?? "",
    })),
  };
}

/** Creates the certificate unless it exists (a retry). `tags` are the generated tags of the platform. */
export async function ensureCertificate(
  lightsail: LightsailClient,
  input: {
    readonly name: string;
    readonly domain: string;
    readonly tags: { key: string; value: string }[];
  },
): Promise<void> {
  if ((await readCertificate(lightsail, input.name)) !== null) return;
  await lightsail.send(
    new CreateCertificateCommand({
      certificateName: input.name,
      domainName: input.domain,
      tags: input.tags,
    }),
  );
}

/** Deletes the certificate; one that is gone already is a clean result (R7). */
export async function deleteCertificate(lightsail: LightsailClient, name: string): Promise<void> {
  await orNull(() => lightsail.send(new DeleteCertificateCommand({ certificateName: name })));
}

/**
 * After a delete: the certificate must no longer show before a new one is requested under the same
 * generated name. If it still shows, the operation is retried later (R7, R16).
 */
export async function requireCertificateGone(
  lightsail: LightsailClient,
  name: string,
): Promise<void> {
  if ((await readCertificate(lightsail, name)) !== null) {
    throw new AwsError({ code: "upstream_unavailable", retryable: true });
  }
}
